SET revenueAccountId = (SELECT id FROM revenueAccounts WHERE saleType = 'A_PRAZO' AND isDefault = TRUE LIMIT 1)
WHERE saleType = 'A_PRAZO' AND revenueAccountId IS NULL AND status = 'ACTIVE';

